//Generated by Claude seems to work fine.

import { jsPDF } from "jspdf";
import { svg2pdf } from "svg2pdf.js";
// @ts-ignore
import unicodeFontUrl from "../fonts/DejaVuSans-subset.ttf?url";

// The standard PDF fonts only cover Latin-1 (WinAnsiEncoding). Labels with
// other characters, e.g., Greek letters or subscripts from display labels
// (see Graph/unicodeMath.js), are rendered with an embedded Unicode font.
const UNICODE_FONT = "DejaVuSans";
const UNICODE_FONT_FILE = "DejaVuSans-subset.ttf";
const beyondLatin1 = /[^\u0000-ÿ]/;

let unicodeFontPromise = null;

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary);
}

async function fetchUnicodeFont() {
  const response = await fetch(unicodeFontUrl);
  if (!response.ok) {
    throw new Error(`Could not load ${unicodeFontUrl}: ${response.status}`);
  }
  const buffer = await response.arrayBuffer();
  const base64 = arrayBufferToBase64(buffer);
  // svg2pdf measures text widths (e.g., for centering) in the browser,
  // so the browser needs to know the font as well
  try {
    const face = new FontFace(UNICODE_FONT, buffer);
    document.fonts.add(await face.load());
  } catch (err) {
    console.warn("Could not register PDF font in browser", err);
  }
  return base64;
}

function loadUnicodeFont() {
  if (!unicodeFontPromise) {
    unicodeFontPromise = fetchUnicodeFont().catch((err) => {
      unicodeFontPromise = null;
      throw err;
    });
  }
  return unicodeFontPromise;
}

async function useUnicodeFont(pdf, svgElement) {
  const unicodeTexts = Array.from(svgElement.querySelectorAll("text")).filter(
    (text) => beyondLatin1.test(text.textContent),
  );
  if (unicodeTexts.length === 0) return;
  try {
    const fontBase64 = await loadUnicodeFont();
    pdf.addFileToVFS(UNICODE_FONT_FILE, fontBase64);
    pdf.addFont(UNICODE_FONT_FILE, UNICODE_FONT, "normal");
    unicodeTexts.forEach((text) =>
      text.setAttribute("font-family", UNICODE_FONT),
    );
  } catch (err) {
    console.error("Could not embed Unicode font in PDF", err);
  }
}

export async function svgToPDF(svgContent) {
  const parser = new DOMParser();
  const svgElement = parser.parseFromString(
    svgContent,
    "image/svg+xml",
  ).documentElement;
  svgElement.style.position = "absolute";
  svgElement.style.left = "-9999px"; // Move the SVG off-screen
  document.body.appendChild(svgElement); // Temporarily add the SVG to the document
  const rect = svgElement.getBoundingClientRect(); // Get the actual size
  document.body.removeChild(svgElement); // Remove the SVG from the document
  const width = rect.width;
  const height = rect.height;
  const pdf = new jsPDF({
    orientation: width > height ? "landscape" : "portrait",
    unit: "pt",
    format: [width, height],
  });
  await useUnicodeFont(pdf, svgElement);
  await svg2pdf(svgElement, pdf, { width, height });
  return pdf;
}
